/**
 * The "no goals" drawing, split into the layers `NoGoalsArt` animates.
 *
 * Storyset's "Mind map" (Work collection), simplified for the app: the girl,
 * her desk, the book and the plant are theirs, unchanged; the three goal
 * ideas, the thought dots, the backdrop and the sparkles were drawn to match
 * `all-logged.svg`. Still their drawing, so the Work credit in
 * `components/settings/credits.ts` stays.
 *
 * Each layer is a whole 500 × 500 SVG holding only its own shapes, so they
 * stack exactly and each can move on its own. The girl is five, in the
 * drawing's own order: `SCENE` is everything painted before her pencil,
 * then `PENCIL`, the `FOREARM` holding it, the `HAND` gripping it, and
 * `SCENE_TOP` — the sleeve and other arm painted over the rest. Only the
 * pencil and the hand move, turning together at the `WRIST`; the forearm
 * stays put, so the tap never opens a gap onto the upper arm.
 *
 * Centres are in the drawing's own 500-unit space: the point a badge floats
 * around, a sparkle twinkles from, or a dot pulses at.
 */

export type ArtLayer = { xml: string; center: readonly [number, number] };

export const VIEWBOX = 500;

/** Where the fist meets the forearm: the hand and pencil tap by turning here. */
export const WRIST = [285, 335] as const;

